const filePath = path.join(dir, 'order_summary.xlsx');
XLSX.writeFile(wb, filePath);
console.log('Created:', filePath);

// 2. Read it back to verify
const wb2 = XLSX.readFile(filePath);
const sheet = wb2.Sheets[wb2.SheetNames[0]];
